package piglatin

import "strings"

func Sentence(sentence string) string {
	words := strings.Fields(sentence)
	for i, word := range words {
		words[i] = pigify(word)
	}
	return strings.Join(words, " ")
}

func pigify(word string) string {
	// Rule 1: word begins with a vowel, or starts with "xr" or "yt".
	if isVowel(word[0]) || strings.HasPrefix(word, "xr") || strings.HasPrefix(word, "yt") {
		return word + "ay"
	}

	// Rules 2-4: find where the leading consonant cluster ends.
	i := 0
	for i < len(word) {
		c := word[i]
		if c == 'q' && i+1 < len(word) && word[i+1] == 'u' {
			// Rule 3: move the "qu" along with the consonants.
			i += 2
			break
		}
		if c == 'y' && i > 0 {
			// Rule 4: "y" acts as a vowel after one or more consonants.
			break
		}
		if isVowel(c) {
			break
		}
		i++
	}
	return word[i:] + word[:i] + "ay"
}

func isVowel(c byte) bool {
	switch c {
	case 'a', 'e', 'i', 'o', 'u':
		return true
	}
	return false
}
